#!/usr/bin/env bash
# Copies the TypeChain bindings (ABI + bytecode) generated by the SmartContracts
# repository into src/contracts. Test-only contracts and Hardhat augmentations are skipped.
#
# Usage: scripts/sync-contracts.sh <path-to-SmartContracts-checkout>
set -euo pipefail

SRC="${1:?Usage: $0 <path-to-SmartContracts-checkout>}/types"
DEST="$(cd "$(dirname "$0")/.." && pwd)/src/contracts"

if [ ! -f "$SRC/index.ts" ]; then
  echo "No TypeChain output found at $SRC. Run 'npx hardhat build' in the SmartContracts repo first." >&2
  exit 1
fi

rm -rf "$DEST"
mkdir -p "$DEST"
cp -R "$SRC/." "$DEST/"

rm -f "$DEST/hardhat.d.ts"
find "$DEST" -name 'ProductPassportEchidnaTest*' -delete
find "$DEST" -name 'index.ts' -exec sed -i.bak '/ProductPassportEchidnaTest/d' {} +
find "$DEST" -name '*.bak' -delete

echo "Synced contract bindings from $SRC into $DEST"
